  "description": "OpenCode plugin that proxies OpenAI OAuth authentication and Codex API calls through a user-specified proxy server",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.0",
    "@types/node": "^25.9.2",
    "typescript": "^5.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "trustedDependencies": [],
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openai",
    "oauth",
    "proxy"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/alexandru/opencode-openai-oauth-proxy"
  }
}
